"use client";

import React from "react";

import ShareButton from "@/registry/open-source/share-button";
import { Facebook, Instagram, Linkedin, Twitter } from "lucide-react";

export default function Usage() {
	return (
		<div className="h-screen w-full flex items-center justify-center relative overflow-hidden bg-background">
			<ShareButton
				links={[
					{
						icon: Facebook,
						onClick: () => null,
					},
					{
						icon: Twitter,
						onClick: () => null,
					},
					{
						icon: Instagram,
						onClick: () => null,
					},
					{
						icon: Linkedin,
						onClick: () => null,
					},
				]}
			>
				Share this link!
			</ShareButton>
		</div>
	);
}

"use client";

import React, { useState } from "react";

import { Button } from "@/components/ui/button";
import { cn } from "@/registry/utilities/cn";
import { LucideIcon } from "lucide-react";

interface ShareLink {
	icon: LucideIcon;
	href?: string;
	onClick?: () => void;
	label?: string;
}

interface ShareButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement> {
	links: ShareLink[];
	children: React.ReactNode;
}

const ShareButton = ({
	className,
	links,
	children,
	...props
}: ShareButtonProps) => {
	const [isHovered, setIsHovered] = useState(false);

	return (
		<div
			className="relative"
			onMouseEnter={() => setIsHovered(true)}
			onMouseLeave={() => setIsHovered(false)}
		>
			<Button
				className={cn(
					"relative min-w-40  rounded-3xl ",
					"bg-background dark:bg-background",
					"hover:bg-background dark:hover:bg-background",
					"text-foreground dark:text-foreground",
					"border border-black/10 dark:border-white/10",
					"transition-[opacity,background-color,color,border-color] duration-300",
					isHovered ? "opacity-0" : "opacity-100",
					className
				)}
				{...props}
			>
				<span className="flex items-center gap-2">{children}</span>
			</Button>

			<div className="absolute left-0 top-0 flex h-10">
				{links.map((link, index) => {
					const Icon = link.icon;
					return (
						<button
							type="button"
							key={index + "share-button"}
							onClick={link.onClick}
							className={cn(
								"h-10",
								"w-10",
								"flex items-center justify-center",
								"bg-background dark:bg-background",
								"text-foreground dark:text-foreground",
								"transition-all duration-300",
								index === 0 && "rounded-l-3xl",
								index === links.length - 1 && "rounded-r-3xl",
								"border-r border-white/10 last:border-r-0 dark:border-black/10",
								"hover:bg-background dark:hover:bg-background",
								"",
								isHovered
									? "translate-x-0 opacity-100"
									: "-translate-x-full opacity-0",
								index === 0 && "duration-200",
								index === 1 && "delay-[50ms] duration-200",
								index === 2 && "delay-100 duration-200",
								index === 3 && "delay-150 duration-200"
							)}
						>
							<Icon className="size-4" />
						</button>
					);
				})}
			</div>
		</div>
	);
};

export default ShareButton;

import * as React from "react";

import { cn } from "@/registry/utilities/cn";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}
